62	 */
63	
64	@RestController
65	@CrossOrigin(exposedHeaders = "errors, content-type")
66	@RequestMapping("/api")
67	public class OwnerRestControllerV1 implements OwnersApi {
68	
69	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
70	
71	    private final ClinicService clinicService;
72	
73	    private final OwnerMapper ownerMapper;
74	
75	    private final PetMapper petMapper;
76	
77	    private final VisitMapper visitMapper;
78	
79	    public OwnerRestControllerV1(ClinicService clinicService,
80	                                 OwnerMapper ownerMapper,
81	                                 PetMapper petMapper,
82	                                 VisitMapper visitMapper) {
83	        this.clinicService = clinicService;
84	        this.ownerMapper = ownerMapper;
85	        this.petMapper = petMapper;
86	        this.visitMapper = visitMapper;
87	    }
88	
89	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
90	    @Override
91	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
92	        Collection<Owner> owners;
93	        if (lastName != null) {
94	            owners = this.clinicService.findOwnerByLastName(lastName);
95	        } else {
96	            owners = this.clinicService.findAllOwners();
97	        }
98	        if (owners.isEmpty()) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
107	        Owner owner = this.clinicService.findOwnerById(ownerId);
108	        if (owner == null) {
109	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
110	        }
111	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
112	    }
113	
114	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
115	    @Override
116	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
117	        HttpHeaders headers = new HttpHeaders();
118	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
119	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
120	        owner.setTelephone(normalizedTelephone);
121	        owner.setEmail(normalizeEmail(owner.getEmail()));
122	        owner.setAddress(normalizeAddress(owner.getAddress()));
123	        validatePostcode(owner.getCity(), owner.getPostcode());
124	        LocalDate effectiveRegistrationDate = owner.getRegistrationDate();
125	        if (effectiveRegistrationDate == null) {
126	            effectiveRegistrationDate = LocalDate.now();
127	        } else if (effectiveRegistrationDate.isAfter(LocalDate.now())) {
128	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
129	                "registrationDate must not be later than the current server date");
130	        }
131	        effectiveRegistrationDate = rollToBusinessDay(effectiveRegistrationDate);
132	        owner.setRegistrationDate(effectiveRegistrationDate);
133	        if (countOwnersRegisteredOn(effectiveRegistrationDate) >= DAILY_CREATE_LIMIT) {
134	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
135	                "the maximum number of owners that may be created today has been reached");
136	        }
137	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
138	        // The household id is deterministic (derived from the last name and postcode), so every
139	        // owner is keyed to its household automatically, regardless of creation order.
140	        this.clinicService.assignHousehold(owner);
141	        boolean householdInUse = this.clinicService.isHouseholdInUse(owner.getHouseholdId(), null);
142	        if (householdInUse && !sharesHousehold) {
143	            throw new ResponseStatusException(HttpStatus.CONFLICT,
144	                "an owner in the same household already exists");
145	        }
146	        if (isIdentityKeyInUse(ownerMapper.toIdentityKey(owner), null)) {
147	            throw new ResponseStatusException(HttpStatus.CONFLICT,
148	                "an owner with the same identity already exists");
149	        }
150	        if (countOwnersInCity(owner.getCity()) >= CITY_CAPACITY) {
151	            throw new ResponseStatusException(HttpStatus.CONFLICT,
152	                "city has reached its maximum number of owners");
153	        }
154	        owner.setCustomerCode(customerCodeFor(owner));
155	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
156	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
157	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
158	        owner.setBulkSignupWarning(
159	            countOwnersRegisteredOn(effectiveRegistrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
160	        // A declared household member (one created with 'sharesHousehold' that joins an existing
161	        // household) is not a suspected duplicate, so it is never flagged as a possible duplicate.
162	        boolean declaredHouseholdMember = sharesHousehold && householdInUse;
163	        Owner softDuplicate = declaredHouseholdMember ? null : findPossibleDuplicate(owner);
164	        owner.setPossibleDuplicate(softDuplicate != null);
165	        owner.setPossibleDuplicateOf(softDuplicate == null ? null : softDuplicate.getId());
166	        this.clinicService.saveOwner(owner);
167	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
168	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
169	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
170	            ownerDto.getMembershipLevel());
171	        headers.setLocation(UriComponentsBuilder.newInstance()
172	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
173	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
174	    }
175	
176	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
177	    @Override
178	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
179	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
180	        if (currentOwner == null) {
181	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
182	        }
183	        currentOwner.setAddress(ownerFieldsDto.getAddress());
184	        currentOwner.setCity(ownerFieldsDto.getCity());
185	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
186	        currentOwner.setLastName(ownerFieldsDto.getLastName());
187	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
188	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
189	        this.clinicService.saveOwner(currentOwner);
190	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
191	    }
192	
193	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
194	    @Transactional
195	    @Override
196	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
197	        Owner owner = this.clinicService.findOwnerById(ownerId);
198	        if (owner == null) {
199	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
200	        }
201	        this.clinicService.deleteOwner(owner);
202	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
203	    }
204	
205	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
206	    @Override
207	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
208	        Owner owner = this.clinicService.findOwnerById(ownerId);
209	        if (owner == null) {
210	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
211	        }
212	        HttpHeaders headers = new HttpHeaders();
213	        Pet pet = petMapper.toPet(petFieldsDto);
214	        owner.setId(ownerId);
215	        pet.setOwner(owner);
216	        pet.getType().setName(null);
217	        this.clinicService.savePet(pet);
218	        PetDto petDto = petMapper.toPetDto(pet);
219	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
220	            .buildAndExpand(pet.getId()).toUri());
221	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
222	    }
223	
224	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
225	    @Override
226	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
227	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
228	        if (currentOwner != null) {
229	            Pet currentPet = this.clinicService.findPetById(petId);
230	            if (currentPet != null) {
231	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
232	                currentPet.setName(petFieldsDto.getName());
233	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
234	                this.clinicService.savePet(currentPet);
235	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
236	            }
237	        }
238	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
239	    }
240	
241	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
242	    @Override
243	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
244	        HttpHeaders headers = new HttpHeaders();
245	        Visit visit = visitMapper.toVisit(visitFieldsDto);
246	        Pet pet = new Pet();
247	        pet.setId(petId);
248	        visit.setPet(pet);
249	        this.clinicService.saveVisit(visit);
250	        VisitDto visitDto = visitMapper.toVisitDto(visit);
251	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
252	            .buildAndExpand(visit.getId()).toUri());
253	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
254	    }
255	
256	
257	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
258	    @Override
259	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
260	        Owner owner = this.clinicService.findOwnerById(ownerId);
261	        if (owner != null) {
262	            Pet pet = owner.getPet(petId);
263	            if (pet != null) {
264	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
265	            }
266	        }
267	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
268	    }
269	
270	    /**
271	     * Builds the customer code for a new owner, formatted {@code '<REGION>-<HASH8>'} where REGION is
272	     * the region derived from the owner's postcode (preferring the postcode, falling back to the
273	     * city table, else {@code 'UNKNOWN'}; see {@link OwnerMapper#regionOf(Owner)}) and HASH8 is the
274	     * first 8 upper-case hex characters of the SHA-256 digest of the owner's normalized E.164
275	     * telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). The code carries no
276	     * sequence number, so it is a stable function of the owner's region and telephone/last-name
277	     * identity rather than of creation order.
278	     *
279	     * @param owner the owner being created, with its telephone already normalized to E.164 form
280	     * @return the assigned customer code
281	     */
282	    private String customerCodeFor(Owner owner) {
283	        String region = ownerMapper.regionOf(owner);
284	        String hash8 = sha256UpperHex(owner.getTelephone() + owner.getLastName()).substring(0, 8);
285	        return region + "-" + hash8;
286	    }
287	
288	    /**
289	     * Computes the SHA-256 digest of the UTF-8 bytes of {@code value} and renders it as an
290	     * upper-case hex string.
291	     *
292	     * @param value the string to hash
293	     * @return the full SHA-256 digest as upper-case hex
294	     */
295	    private static String sha256UpperHex(String value) {
296	        try {
297	            byte[] digest = MessageDigest.getInstance("SHA-256")
298	                .digest(value.getBytes(StandardCharsets.UTF_8));
299	            StringBuilder sb = new StringBuilder(digest.length * 2);
300	            for (byte b : digest) {
301	                sb.append(String.format("%02X", b));
302	            }
303	            return sb.toString();
304	        } catch (NoSuchAlgorithmException ex) {
305	            throw new IllegalStateException("SHA-256 not available", ex);
306	        }
307	    }
308	
309	    /**
310	     * The maximum number of owners allowed to live in a single city. A create is rejected once the
311	     * owner's city already contains this many owners.
312	     */
313	    private static final int CITY_CAPACITY = 50;
314	
315	    /**
316	     * The maximum number of owners that may be created on a single day. A create is rejected with
317	     * {@link HttpStatus#TOO_MANY_REQUESTS} once this many owners already have today's
318	     * {@code registrationDate}.
319	     */
320	    private static final int DAILY_CREATE_LIMIT = 100;
321	
322	    /**
323	     * The number of owners that must already have been created for the current day before a new
324	     * create is flagged with {@code bulkSignupWarning}. The warning is set once more than this many
325	     * owners already carry today's {@code registrationDate}.
326	     */
327	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
328	
329	    /**
330	     * Rolls a registration date forward onto a business day: a date that falls on a Saturday or
331	     * Sunday is moved forward to the following Monday, while a date already on a weekday is returned
332	     * unchanged. Applied to the effective registration date (supplied or defaulted to the server
333	     * date) so that the stored {@code registrationDate}, and every value derived from it, always
334	     * falls on a business day.
335	     *
336	     * @param date the effective registration date
337	     * @return the same date when it is a weekday, otherwise the following Monday
338	     */
339	    private static LocalDate rollToBusinessDay(LocalDate date) {
340	        return switch (date.getDayOfWeek()) {
341	            case SATURDAY -> date.plusDays(2);
342	            case SUNDAY -> date.plusDays(1);
343	            default -> date;
344	        };
345	    }
346	
347	    /**
348	     * Counts the existing owners whose {@code registrationDate} equals the given (already
349	     * business-day-adjusted) date, i.e. the number of owners that have already been created for that
350	     * business day. Called before a new owner is saved, so the returned value reflects the number of
351	     * owners created for that day prior to this create.
352	     *
353	     * @param date the adjusted business-day registration date to count against
354	     * @return the number of existing owners registered on that date
355	     */
356	    private int countOwnersRegisteredOn(LocalDate date) {
357	        return (int) this.clinicService.findAllOwners().stream()
358	            .filter(existing -> date.equals(existing.getRegistrationDate()))
359	            .count();
360	    }
361	
362	    /**
363	     * Counts the existing owners that live in the given city, comparing city names case-insensitively.
364	     *
365	     * @param city the city to count owners for
366	     * @return the number of existing owners in that city
367	     */
368	    private int countOwnersInCity(String city) {
369	        return (int) this.clinicService.findAllOwners().stream()
370	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
371	            .count();
372	    }
373	
374	    /**
375	     * Builds the membership number for a new owner, formatted {@code '<customerCode>-M<YY>'} where YY is
376	     * the last two digits of the registration date's year (e.g. {@code 'NSW-1A2B3C4D-M26'}).
377	     *
378	     * @param customerCode     the owner's assigned customer code
379	     * @param registrationDate the owner's registration date
380	     * @return the assigned membership number
381	     */
382	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
383	        String yy = String.format("%02d", registrationDate.getYear() % 100);
384	        return String.format("%s-M%s", customerCode, yy);
385	    }
386	
387	    /**
388	     * Counts the existing owners that already share the given first name and last name, comparing
389	     * both case-insensitively. Called before a new owner is saved, so the returned value reflects
390	     * the number of namesakes that existed prior to this create.
391	     *
392	     * @param firstName the new owner's first name
393	     * @param lastName  the new owner's last name
394	     * @return the number of existing owners with the same first and last name
395	     */
396	    private int countNamesakes(String firstName, String lastName) {
397	        int count = 0;
398	        for (Owner existing : this.clinicService.findAllOwners()) {
399	            if (firstName.equalsIgnoreCase(existing.getFirstName())
400	                && lastName.equalsIgnoreCase(existing.getLastName())) {
401	                count++;
402	            }
403	        }
404	        return count;
405	    }
406	
407	    /**
408	     * Counts the existing owners that already belong to the given household (i.e. that share the
409	     * given {@code householdId}). Called before a new owner is saved, so adding one for the owner
410	     * being created yields the household's total size at the moment of creation. Owners without a
411	     * household id are ignored.
412	     *
413	     * @param householdId the new owner's assigned household id
414	     * @return the number of existing owners already in that household
415	     */
416	    private int countHouseholdMembers(String householdId) {
417	        if (householdId == null) {
418	            return 0;
419	        }
420	        int count = 0;
421	        for (Owner existing : this.clinicService.findAllOwners()) {
422	            if (householdId.equals(existing.getHouseholdId())) {
423	                count++;
424	            }
425	        }
426	        return count;
427	    }
428	
429	    /**
430	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. When
431	     * the value carries a leading {@code '+'} the following country code and digits are kept as-is;
432	     * otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
433	     * the national digits. The result must be a {@code '+'} followed by 8 to 15 digits. This E.164
434	     * string is what gets stored and returned.
435	     *
436	     * <p>For example {@code "0412 345 678"} is normalized to {@code "+61412345678"}.
437	     *
438	     * <p>Once in E.164 form the national-number length is validated against the country code: a
439	     * {@code +61} (Australia) number must carry exactly 9 national digits and a {@code +1} (NANP)
440	     * number exactly 10 (see {@link E164PhoneNumbers#NATIONAL_LENGTHS}). Country codes without a configured
441	     * rule are accepted on the general 8-to-15 digit length alone.
442	     *
443	     * @param telephone the raw telephone value supplied by the client
444	     * @return the normalized E.164 telephone number
445	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the value cannot form a
446	     *                                 valid E.164 number (unexpected characters, not 8 to 15 digits
447	     *                                 after the {@code '+'}, or the wrong national-number length for
448	     *                                 its country code)
449	     */
450	    private static String normalizeTelephone(String telephone) {
451	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
452	        String digits;
453	        if (cleaned.startsWith("+")) {
454	            digits = cleaned.substring(1);
455	        } else {
456	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
457	            digits = "61" + national;
458	        }
459	        if (!digits.matches("[0-9]{8,15}")) {
460	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
461	                "telephone could not be normalized to a valid E.164 number");
462	        }
463	        validateNationalNumberLength(digits);
464	        return "+" + digits;
465	    }
466	
467	    /**
468	     * Validates the national-number length of an E.164 number (its digits, without the leading
469	     * {@code '+'}) against its country code. The longest dialling code that prefixes the number (see
470	     * {@link E164PhoneNumbers#countryCode}) selects the rule; if none is configured the number passes
471	     * (only the general 8-to-15 digit rule applies).
472	     *
473	     * @param digits the E.164 digits without the leading {@code '+'}
474	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the number of national
475	     *                                 digits does not match the country code's required length
476	     */
477	    private static void validateNationalNumberLength(String digits) {
478	        E164PhoneNumbers.countryCode(digits)
479	            .ifPresent(code -> {
480	                int nationalLength = digits.length() - code.length();
481	                int required = E164PhoneNumbers.NATIONAL_LENGTHS.get(code);
482	                if (nationalLength != required) {
483	                    throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
484	                        "telephone must have " + required
485	                            + " national digits for country code +" + code);
486	                }
487	            });
488	    }
489	
490	    /**
491	     * Basic syntactic email validation: a non-empty local part, an {@code @}, and a domain
492	     * containing at least one dot, none of the three sections containing whitespace or an
493	     * additional {@code @}.
494	     */
495	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
496	
497	    /**
498	     * Disposable email domains that are not accepted for an owner. An email whose domain is on this
499	     * blocklist is rejected with {@link HttpStatus#BAD_REQUEST}. Entries are lower-case and matched
500	     * case-insensitively against the domain (the part after the {@code @}).
501	     */
502	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
503	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
504	
505	    /**
506	     * Validates and normalizes an optional owner email address. A {@code null} value is left as is
507	     * (email is optional). When a value is supplied it must be a syntactically valid address whose
508	     * domain is not on the disposable-domain blocklist; the value is then stored and returned
509	     * lower-cased.
510	     *
511	     * @param email the raw email value supplied by the client, possibly {@code null}
512	     * @return the lower-cased email, or {@code null} when none was supplied
513	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a value is present but
514	     *                                 is not a syntactically valid address, or its domain is on the
515	     *                                 disposable-domain blocklist
516	     */
517	    private static String normalizeEmail(String email) {
518	        if (email == null) {
519	            return null;
520	        }
521	        if (!EMAIL_PATTERN.matcher(email).matches()) {
522	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
523	                "email must be a syntactically valid address");
524	        }
525	        String normalized = email.toLowerCase(Locale.ROOT);
526	        String domain = normalized.substring(normalized.indexOf('@') + 1);
527	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
528	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
529	                "email domain " + domain + " is not allowed");
530	        }
531	        return normalized;
532	    }
533	
534	    /**
535	     * Fixed region-to-inclusive-postcode-range table. The postcode of an owner whose city maps to a
536	     * known region (via {@link OwnerMapper#CITY_REGION}) must fall within its region's range: NSW
537	     * 2000-2099, VIC 3000-3099, QLD 4000-4099. Each entry is {@code {low, high}} inclusive.
538	     */
539	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
540	        "NSW", new int[] {2000, 2099},
541	        "VIC", new int[] {3000, 3099},
542	        "QLD", new int[] {4000, 4099});
543	
544	    /**
545	     * Validates an owner's optional postcode against the city's region. Postcode is validated only
546	     * when present ({@code null} is accepted, keeping the request contract backward-compatible). The
547	     * four-digit format is enforced by request validation; here the value is range-checked: when the
548	     * city maps to a known region (via {@link OwnerMapper#CITY_REGION}) the postcode must fall within
549	     * that region's inclusive range (see {@link #REGION_POSTCODE_RANGES}). A city with no known region
550	     * accepts any four-digit postcode.
551	     *
552	     * @param city     the owner's city
553	     * @param postcode the owner's postcode, possibly {@code null}
554	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a supplied postcode is
555	     *                                 out of range for the city's region
556	     */
557	    private static void validatePostcode(String city, String postcode) {
558	        if (postcode == null) {
559	            return;
560	        }
561	        String region = OwnerMapper.CITY_REGION.get(city);
562	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
563	        if (range == null) {
564	            return;
565	        }
566	        int value = Integer.parseInt(postcode);
567	        if (value < range[0] || value > range[1]) {
568	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
569	                "postcode " + postcode + " is not valid for region " + region);
570	        }
571	    }
572	
573	    /**
574	     * Common street-type abbreviations expanded to their full word during address normalization.
575	     * Keys and values are upper-case; matching is done per whitespace-delimited token.
576	     */
577	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
578	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
579	
580	    /**
581	     * Normalizes an owner address for storage. Leading/trailing whitespace is trimmed and internal
582	     * runs of whitespace are collapsed to a single space, the value is upper-cased, and common
583	     * street-type abbreviations are expanded per token ({@code ST -> STREET}, {@code RD -> ROAD},
584	     * {@code AVE -> AVENUE}). This normalized value is what gets stored and returned.
585	     *
586	     * <p>For example {@code "  12  main  st "} is normalized to {@code "12 MAIN STREET"}.
587	     *
588	     * @param address the raw address supplied by the client, possibly {@code null}
589	     * @return the normalized address
590	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the address is blank
591	     *                                 after normalization (required field)
592	     */
593	    private static String normalizeAddress(String address) {
594	        String collapsed = address == null ? "" : address.trim().replaceAll("\\s+", " ");
595	        if (collapsed.isEmpty()) {
596	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
597	                "address must not be blank");
598	        }
599	        String[] tokens = collapsed.toUpperCase(Locale.ROOT).split(" ");
600	        StringBuilder normalized = new StringBuilder();
601	        for (int i = 0; i < tokens.length; i++) {
602	            if (i > 0) {
603	                normalized.append(' ');
604	            }
605	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
606	        }
607	        return normalized.toString();
608	    }
609	
610	    /**
611	     * Determines whether the given whole identity key already belongs to any owner other than the
612	     * one identified by {@code excludeId} (pass {@code null} to consider every owner, e.g. on
613	     * create). The key is derived in one place — {@link OwnerMapper#toIdentityKey(Owner)}, the same
614	     * method that builds the {@code identityKey} returned on the DTO — so the value governing the
615	     * 409 is exactly the value clients see. Only an exact full-key match counts as a duplicate.
616	     *
617	     * @param identityKey the identity key to look for
618	     * @param excludeId   id of an owner to ignore during the check, or {@code null} for none
619	     * @return {@code true} if another owner already has the same identity key
620	     */
621	    private boolean isIdentityKeyInUse(String identityKey, Integer excludeId) {
622	        for (Owner existing : this.clinicService.findAllOwners()) {
623	            if (excludeId != null && excludeId.equals(existing.getId())) {
624	                continue;
625	            }
626	            if (identityKey.equals(ownerMapper.toIdentityKey(existing))) {
627	                return true;
628	            }
629	        }
630	        return false;
631	    }
632	
633	    /**
634	     * Finds the existing owner that the given (not-a-hard-duplicate) new owner is a possible
635	     * (soft) duplicate of: one that shares the new owner's last name (compared case-insensitively)
636	     * and postcode while carrying a <em>different</em> normalized telephone. A hard duplicate
637	     * (identical identity key) has already been rejected with a 409 before this runs, so this
638	     * flags only the softer last-name/postcode overlap. The match with the lowest id is returned
639	     * so the result is deterministic when several owners qualify.
640	     *
641	     * @param owner the new owner being created, with its telephone already normalized
642	     * @return the matching existing owner, or {@code null} when none qualifies
643	     */
644	    private Owner findPossibleDuplicate(Owner owner) {
645	        if (owner.getLastName() == null || owner.getPostcode() == null) {
646	            return null;
647	        }
648	        return this.clinicService.findAllOwners().stream()
649	            .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName()))
650	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
651	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
652	            .min(Comparator.comparingInt(Owner::getId))
653	            .orElse(null);
654	    }
655	
656	}
